import type { DashboardDefinition } from './dashboard-definition-model';
import type { SavedReportDefinition } from './saved-report-definition-model';

export const DashboardWidgetWidthKeyToLabel = {
  'Full': 'Full',
  'Half': 'Half',
  'Third': 'Third'
} as const;
export type DashboardWidgetWidthKey = keyof typeof DashboardWidgetWidthKeyToLabel;

export interface DashboardWidget {
  /**
   * @displayName Dashboard Widget ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Title
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  title: string;
  /**
   * @displayName Created At
   * @validationRule Required for create/update operations
   */
  createdAt: string;
  /**
   * @displayName Dashboard Definition
   * @validationRule Required for create/update operations
   */
  dashboardDefinition: Pick<DashboardDefinition, 'id' | 'name1'>;
  /**
   * @displayName Is Deleted
   * @validationRule Required for create/update operations
   */
  isDeleted: boolean;
  /**
   * @displayName Saved Report Definition
   * @validationRule Required for create/update operations
   */
  savedReportDefinition: Pick<SavedReportDefinition, 'id' | 'name1'>;
  /**
   * @displayName Sort Order
   * @validationRule Required for create/update operations
   */
  sortOrder: number;
  /**
   * @displayName Width
   * @validationRule Required for create/update operations
   */
  widthKey: DashboardWidgetWidthKey;
}

export const _DashboardWidget = 'DashboardWidget' as const;